import React, { PropsWithChildren, useContext, useMemo } from 'react';

import { DataTableProps } from '../DataTable/DataTable.js';
import type {
  RequiredDataTableConfiguration,
  DataTableContextConfig,
} from '../types/table-config-types.js';
import {
  deserializeConfig,
  buildDataTableConfig,
} from '../utils/datatable-config-utils.js';

export const DataTableConfigContext = React.createContext<
  DataTableContextConfig | string
>({});

/** Provider for the DataTable API config that can be shared across design */
export const DataTableConfig = DataTableConfigContext.Provider;

export const useDataTableConfig = (
  props: PropsWithChildren<DataTableProps>,
): RequiredDataTableConfiguration => {
  const contextConfig = useContext(DataTableConfigContext);

  const config = useMemo(() => {
    return typeof contextConfig === 'string'
      ? deserializeConfig(contextConfig)
      : contextConfig;
  }, [contextConfig]);
  return buildDataTableConfig(props, config);
};
